// agent.v1 descriptor for Cursor chat and model listing.
// Adapted from the MIT-licensed proto used by oh-my-pi / pi-cursor-provider.
import { fileDesc } from '@bufbuild/protobuf/codegenv2'

const file = fileDesc("")
const byName = new Map(file.messages.map((message) => [message.typeName, message]))

export function cursorSchema(typeName) {
  const schema = byName.get(typeName)
  if (!schema) throw new Error(`Missing Cursor schema ${typeName}`)
  return schema
}
